from boltons.cacheutils import cachedproperty

class A:
    @cachedproperty
    def foo(self):
        """My docstring"""
        return 1

def test_docstring():
    # Check if the cachedproperty instance has the docstring of the wrapped function
    assert A.foo.__doc__ == "My docstring", f"Expected 'My docstring', got {A.foo.__doc__}"

if __name__ == "__main__":
    try:
        test_docstring()
        print("REPRO PASS")
    except AssertionError as e:
        print(f"REPRO FAIL: {e}")

